<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');$keys=['school_name','school_address','school_phone','school_email','school_website','academic_year'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');foreach($keys as $k){$s=$pdo->prepare("INSERT INTO school_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$s->execute([$k,$_POST[$k]??'']);}audit($pdo,'settings','Updated school settings');header('Location:settings.php');exit;}$v=[];foreach($keys as $k)$v[$k]=school_setting($pdo,$k);$pageTitle='Settings';$base='../';require __DIR__.'/../includes/header.php';?><div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>School Settings</h1><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php foreach($keys as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><input name="<?=$k?>" value="<?=e($v[$k])?>"></label><?php endforeach;?><button class="btn">Save Settings</button></form></div></section></div><?php require __DIR__.'/../includes/footer.php';?>